// Simulated product database for the admin catalog.
//
// In production `getAllProducts` would query your product DB. Here it reads an
// in-memory store so the "Sync latest catalog" flow is observable: each sync
// pulls a newer snapshot from the upstream ERP/PIM (updated pricing, inventory,
// availability) and the catalog views pick it up after the cache is refreshed.

type Product = {
  id: number
  name: string
  price: number
  inventory: number
  available: boolean
}

// Local catalog store (what admin views read through `getProducts`).
let products: Product[] = [
  { id: 1, name: 'Laptop', price: 999, inventory: 120, available: true },
  { id: 2, name: 'Phone', price: 699, inventory: 80, available: true },
  { id: 3, name: 'Tablet', price: 499, inventory: 0, available: false },
  { id: 4, name: 'Headphones', price: 199, inventory: 300, available: true },
  { id: 5, name: 'Watch', price: 299, inventory: 45, available: true },
]

let catalogVersion = 1
let lastSyncedAt: string | null = null

// Read the current catalog. Simulates a real DB query (latency we want to
// avoid paying on every request -> that is what the `products` cache is for).
export async function getAllProducts(): Promise<Product[]> {
  await new Promise((resolve) => setTimeout(resolve, 100))
  return products.map((p) => ({ ...p }))
}

export function getCatalogMeta() {
  return { version: catalogVersion, lastSyncedAt }
}

// Pull the latest catalog from the upstream ERP/PIM into the local store.
// Sync jobs touch thousands of SKUs, so this is intentionally slow -- this is
// exactly the work we do NOT want to block admin requests on. It is run in the
// background (via `after()`) by the sync Server Action.
export async function syncCatalogFromUpstream() {
  // Emulate a bulk sync over thousands of SKUs.
  await new Promise((resolve) => setTimeout(resolve, 1500))

  products = products.map((p) => ({
    ...p,
    // Upstream repricing: ~10% price drop.
    price: Math.max(1, Math.round(p.price * 0.9)),
    // Replenished inventory.
    inventory: p.inventory + 50,
    // Re-availability of previously out-of-stock items.
    available: true,
  }))

  catalogVersion += 1
  lastSyncedAt = new Date().toISOString()

  return { version: catalogVersion, lastSyncedAt }
}

