import { unstable_cache } from 'next/cache'
import { getAllProducts, getCatalogMeta } from '@/lib/db'

export type Product = {
  id: number
  name: string
  price: number
  inventory: number
  available: boolean
}

export type Catalog = {
  items: Product[]
  version: number
  lastSyncedAt: string | null
}

// Single, shared cached accessor for the product catalog.
//
// The catalog is read-heavy, so we cache the (slow) DB query under the
// `products` cache tag. Day-to-day browsing reads from this cache instead of
// re-querying on every request. Any admin view that depends on catalog data
// should read through `getProducts` so a single `revalidateTag('products')`
// (triggered after a sync) refreshes them all consistently.
export const getProducts = unstable_cache(
  async (): Promise<Catalog> => {
    const items = await getAllProducts()
    const { version, lastSyncedAt } = getCatalogMeta()
    return { items, version, lastSyncedAt }
  },
  ['products'],
  { tags: ['products'], revalidate: 3600 },
)

