import { after } from 'next/server'
import { revalidateTag } from 'next/cache'
import { getProducts } from '@/lib/products'
import { syncCatalogFromUpstream } from '@/lib/db'
import { SubmitButton } from './submit-button'

// Admin catalog is read-heavy and should feel fast, so the page renders per
// request but reads catalog data from the `products`-tagged data cache (no
// re-query on every request). The expensive work only happens on a sync.
export const dynamic = 'force-dynamic'

// Inline Server Action for the "Sync latest catalog" trigger.
//
// It returns immediately so the admin can keep working -- the page re-renders
// fast with the (still cached, briefly stale) catalog. The slow sync over
// thousands of SKUs is deferred to `after()`, which runs only after the
// response has been sent. Once the sync completes we invalidate the `products`
// cache tag; the next read (here or in any other view sharing the tag)
// repopulates the cache with fresh data, giving eventual consistency across
// catalog views without forcing every request to block on fresh data.
async function syncCatalogAction() {
  'use server'

  after(async () => {
    await syncCatalogFromUpstream()
    revalidateTag('products')
  })
}

export default async function AdminCatalogPage() {
  const { items, version, lastSyncedAt } = await getProducts()

  return (
    <main style={{ maxWidth: 960, margin: '0 auto', padding: 24, fontFamily: 'system-ui, sans-serif' }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', gap: 16, flexWrap: 'wrap' }}>
        <div>
          <h1 style={{ margin: 0 }}>Product Catalog</h1>
          <p style={{ margin: '4px 0 0', color: '#555' }}>
            Catalog version {version}
            {lastSyncedAt ? ` · last synced ${new Date(lastSyncedAt).toLocaleString()}` : ' · not yet synced'}
          </p>
        </div>

        <form action={syncCatalogAction}>
          <SubmitButton />
        </form>
      </header>

      <p style={{ color: '#666', fontSize: 14 }}>
        Syncing pulls the latest pricing, inventory, and availability from the
        upstream ERP/PIM. It runs in the background, so you can keep working --
        the list may be briefly stale and will update shortly after the sync
        finishes.
      </p>

      <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: 16 }}>
        <thead>
          <tr style={{ textAlign: 'left', borderBottom: '2px solid #ddd' }}>
            <th style={{ padding: '8px' }}>ID</th>
            <th style={{ padding: '8px' }}>Name</th>
            <th style={{ padding: '8px' }}>Price</th>
            <th style={{ padding: '8px' }}>Inventory</th>
            <th style={{ padding: '8px' }}>Available</th>
          </tr>
        </thead>
        <tbody>
          {items.map((product) => (
            <tr key={product.id} style={{ borderBottom: '1px solid #eee' }}>
              <td style={{ padding: '8px' }}>{product.id}</td>
              <td style={{ padding: '8px' }}>{product.name}</td>
              <td style={{ padding: '8px' }}>${product.price}</td>
              <td style={{ padding: '8px' }}>{product.inventory}</td>
              <td style={{ padding: '8px' }}>
                {product.available ? 'Yes' : 'No'}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

